let context;
export function signal(kind,volume=.5){if(!volume)return;try{context??=new (window.AudioContext||window.webkitAudioContext)();context.resume();const now=context.currentTime,notes=({plop:[340,180],coin:[1050,1450],achievement:[660,990,1320],boost:[190,450,880],rescue:[520,780,1040],splash:[110,80]})[kind]||[720];notes.forEach((f,i)=>{const o=context.createOscillator(),g=context.createGain();o.type=kind==='boost'?'triangle':'sine';o.frequency.setValueAtTime(f,now+i*.075);o.frequency.exponentialRampToValueAtTime(Math.max(40,f*(kind==='plop'?.45:1.2)),now+i*.075+.18);g.gain.setValueAtTime(.0001,now+i*.075);g.gain.linearRampToValueAtTime(.09*volume,now+i*.075+.012);g.gain.exponentialRampToValueAtTime(.0001,now+i*.075+.45);o.connect(g);g.connect(context.destination);o.start(now+i*.075);o.stop(now+i*.075+.5);});}catch{}}
